function numbers(p){const available=numberRows(p);if(!available[numberRow])numberRow=firstNumberRow(p);const values=available[numberRow],value=chosenNumber??values[numberIndex];const chart=!advanced(p)?chartMarkup(hundredState()):'';return `<section class="lesson number-adventure${chart?' has-hundred':''}${advanced(p)?' has-read-grid':''}">${landscape()}<div class="adventure-top"><span class="world-badge">${gradeFor(p)}${gradeFor(p)===1?'re':'e'} année · ${esc(childName(p))}</span></div><h1>${advanced(p)?'Nombres de 0 à 9 999':'Mon jardin des nombres'}</h1>${chart}<label>Ligne<select id="number-row">${Object.keys(available).map(k=>`<option ${k===numberRow?'selected':''}>${k}</option>`).join('')}</select></label><label>Choisis un nombre de 0 à ${advanced(p)?9999:99}<input id="chosen-number" type="number" inputmode="numeric" min="0" max="${advanced(p)?9999:99}" value="${value}"></label><button data-action="row-mode">${wholeRow?'Un nombre à la fois':'Toute la ligne'}</button><div class="reading" data-number-display>${wholeRow?values.join(' · '):value}</div>${advanced(p)?readAloudMarkup():''}<p data-number-decomposition>${value} = ${decompose(value)||'0'}</p><details><summary>Voir le nombre en mots</summary><p data-number-words>${numberWords(value)}</p></details>${speedControl()}<button data-action="number-audio">Écouter le nombre</button><button data-action="silence">Arrêter l’écoute</button><p class="audio-status number-audio-status" role="status">${esc(voiceMessage||'Écoute le nombre, puis essaie de le redire.')}</p><details class="number-audio-source"><summary>Les voix des nombres</summary><p>Les extraits de <a href="https://pedagofa.cssdm.gouv.qc.ca/1o/1o-13/" target="_blank" rel="noopener noreferrer">PédagoFA · CSSDM</a> sont associés aux nombres. La narratrice complète les morceaux manquants.</p></details>${grokMarkup('number')}${oralPractice(wholeRow)}<div id="number-coach-mount" ${wholeRow?'hidden':''}>${numberCoachMarkup(value)}</div><details data-number-recorder><summary>Mon studio · réécouter ma voix</summary><p>Enregistre-toi pour réécouter avec un adulte. Ta voix reste sur cet appareil et s’efface en quittant l’activité.</p><button data-action="record" ${recording||micPending?'disabled':''}>Enregistrer ma voix</button><button data-action="stop-record" ${!recording?'disabled':''}>Terminer</button><p role="status">${esc(mediaMessage)}</p>${recordURL?`<audio controls src="${recordURL}"></audio>`:''}</details><button data-action="number-prev" ${numberIndex===0?'disabled':''}>Précédent</button><button data-action="number-next" ${numberIndex===9?'disabled':''}>Suivant</button><p><span data-number-position>${chosenNumber!==null?'Nombre choisi pour s’entraîner.':'Nombre '+(numberIndex+1)+'/10.'}</span> Le parent écoute toute la ligne avant de confirmer. Le retour vocal sur un nombre ne valide pas toute la ligne.</p><button data-action="row-confirm" ${chosenNumber!==null?'disabled':''}>Parent : ligne lue sans hésitation</button><button data-action="row-retry">Réessayer un autre soir</button><p role="status">${esc(settings(p).rowStatus?.[numberRow]||'Lecture à vérifier ensemble.')}</p><button data-action="library-numbers">📚 Mes fiches de nombres à mon niveau</button><button data-action="home">Retour au jardin</button></section>`;}
// Une série jouée par une enfant compte au moins cinq questions : les petites listes
// (deux mots, deux sons) sont complétées par des cartes proches du même niveau.
// Une série : 8 questions en 1re année, 10 en 3e année (au lieu de 5), si la banque en a assez.
const seriesLength=p=>advanced(p)?10:8;
function fillSeries(items,subject){
 const p=profile(),min=seriesLength(p);
 if(items.length>=min||!items.length||items[0].island||!items.every(q=>Array.isArray(q.choices)&&q.choices.length))return items;
 const french=subject==='Français'||Object.hasOwn(skills,subject);
 if(!french&&subject!=='Lecture'&&subject!=='Maths')return items;
 const have=new Set(items.map(q=>q.id)),skill=items[0].skill;
 const bank=subject==='Maths'?mathsFor(p):subject==='Lecture'?storyCards(p):[...readingBank(p).filter(q=>q.skill===skill),...readingBank(p).filter(q=>q.skill!==skill&&q.skill!=='syllabes'),...readingBank(p).filter(q=>q.skill==='syllabes')];
 const out=[...items];
 for(const q of bank){if(out.length>=min)break;if(!have.has(q.id)&&Array.isArray(q.choices)&&q.choices.length){have.add(q.id);out.push(q);}}
 return out;
}
function begin(items,subject,{fill=true}={}){if(fill)items=fillSeries(items,subject);items=items.map(q=>beginnerCard(q,profile(),subject));oralWordOpenKey=null;cleanup();const ordered=items[0]?.island?items:adaptiveCards(profile(),items,today());session={items:ordered.slice(0,seriesLength(profile())),remaining:ordered.slice(seriesLength(profile())),index:0,calibration:false,subject:Object.hasOwn(skills,subject)?'Français':subject};feedback=null;helped=false;view='mission';render();document.querySelector('#main').focus();introduce();}
function gardenAction(a){const p=profile(),g=settings(p);if(a==='numbers'){cleanup();numberRow=firstNumberRow(p);numberIndex=0;chosenNumber=null;view='numbers';render();return true;}if(a==='row-mode'){cleanup();voiceMessage='';chosenNumber=null;wholeRow=!wholeRow;render();return true;}if(a==='number-audio'){const input=document.querySelector('#chosen-number'),n=Number(input?.value),current=chosenNumber??numberRows(p)[numberRow][numberIndex];if(input&&(input.value===''||!Number.isInteger(n)||n<0||n>(advanced(p)?9999:99))){cleanup();voiceMessage='Choisis un nombre entier de 0 à '+(advanced(p)?9999:99)+'.';render();return true;}if(input&&n!==current){chosenNumber=n;wholeRow=false;}speakText(wholeRow?numberRows(p)[numberRow].map(numberWords).join('. '):numberWords(chosenNumber??numberRows(p)[numberRow][numberIndex]));return true;}if(a==='number-next'||a==='number-prev'){cleanup();chosenNumber=null;const step=a==='number-next'?1:-1,at=numberIndex+step;if(at>=0&&at<=9)numberIndex=at;else{const to=neighbourRow(p,step);if(to!==numberRow){numberRow=to;numberIndex=step>0?0:9;}}render();return true;}if(a==='row-confirm'||a==='row-retry'){cleanup();g.rowStatus??={};g.rowStatus[numberRow]=a==='row-confirm'?'Parent : lecture sans hésitation confirmée le '+torontoDay():'À reprendre un autre soir, avec de l’aide si besoin.';credit(p,'practice',new Date(),{subject:'Maths',result:a==='row-confirm'?'parent-confirmed':'retry'});persist();render();return true;}if(a==='reading-session'||a==='spelling-session'){credit(p,a==='reading-session'?'reading':'spelling',new Date(),{minutes:g.goal.minutes});persist();render();return true;}return false;}
